for (int ix = 0; ix < elem_count; ++ix) {
    Point *p = &((Point3d*)ptr)[ix];
    delete p;
}

code_example:
struct Point { virtual ~Point() {} };
struct Point3d : Point { ~Point3d() {} };
void process(void* ptr, int elem_count) {
    for (int ix = 0; ix < elem_count; ++ix) {
        Point *p = &((Point3d*)ptr)[ix];
        delete p;
    }
}
